import json
import os
from dataclasses import dataclass, field


@dataclass
class Task:
    task_id: str
    prompt: str
    repo: str
    attempts: int = 0
    status: str = "queued"
    notes: list = field(default_factory=list)


class Queue:
    def __init__(self, path):
        self.path = path
        self.tasks = []
        if os.path.exists(path):
            with open(path) as handle:
                for row in json.load(handle):
                    self.tasks.append(Task(**row))

    def save(self):
        tmp = self.path + ".tmp"
        with open(tmp, "w") as handle:
            json.dump([t.__dict__ for t in self.tasks], handle, indent=2)
        os.replace(tmp, self.path)

    def add(self, task_id, prompt, repo):
        for task in self.tasks:
            if task.task_id == task_id:
                raise ValueError("duplicate task id: " + task_id)
        self.tasks.append(Task(task_id, prompt, repo))
        self.save()

    def next_task(self):
        for task in self.tasks:
            if task.status == "queued":
                return task
        return None

    def mark(self, task_id, status, note=None):
        for task in self.tasks:
            if task.task_id == task_id:
                task.status = status
                task.attempts += 1
                if note:
                    task.notes.append(note)
                self.save()
                return task
        raise KeyError(task_id)

    def summary(self):
        counts = {}
        for task in self.tasks:
            counts[task.status] = counts.get(task.status, 0) + 1
        return counts
